# TCP/IP Server in C

Here's a comprehensive TCP/IP server implementation in C with detailed comments.

## Basic TCP Server

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 5

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Step 1: Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }
    printf("Socket created successfully\n");

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        exit(EXIT_FAILURE);
    }

    // Step 2: Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;  // Accept connections on any interface
    server_addr.sin_port = htons(PORT);         // Convert to network byte order

    // Step 3: Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Socket bound to port %d\n", PORT);

    // Step 4: Listen for connections
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Server listening on port %d...\n", PORT);

    // Step 5: Accept and handle connections
    while (1) {
        printf("\nWaiting for a connection...\n");

        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        // Print client information
        printf("Connection accepted from %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        // Step 6: Communicate with client
        while (1) {
            memset(buffer, 0, BUFFER_SIZE);

            // Receive data from client
            bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

            if (bytes_read < 0) {
                perror("Receive failed");
                break;
            } else if (bytes_read == 0) {
                printf("Client disconnected\n");
                break;
            }

            printf("Received: %s", buffer);

            // Check for exit command
            if (strncmp(buffer, "exit", 4) == 0) {
                printf("Client requested disconnect\n");
                break;
            }

            // Echo back to client (simple echo server)
            char response[BUFFER_SIZE + 20];
            snprintf(response, sizeof(response), "Server received: %s", buffer);

            if (send(client_fd, response, strlen(response), 0) < 0) {
                perror("Send failed");
                break;
            }
        }

        // Close client connection
        close(client_fd);
        printf("Client connection closed\n");
    }

    // Close server socket (unreachable in this example)
    close(server_fd);
    return 0;
}
```

## Multi-threaded TCP Server

This version handles multiple clients simultaneously using threads:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 10

// Structure to pass client info to thread
typedef struct {
    int client_fd;
    struct sockaddr_in client_addr;
    int client_id;
} client_info_t;

// Global client counter
int client_count = 0;
pthread_mutex_t count_mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread function to handle client
void *handle_client(void *arg) {
    client_info_t *client = (client_info_t *)arg;
    char buffer[BUFFER_SIZE];
    int bytes_read;

    printf("[Client %d] Connected from %s:%d\n",
           client->client_id,
           inet_ntoa(client->client_addr.sin_addr),
           ntohs(client->client_addr.sin_port));

    // Send welcome message
    char welcome[100];
    snprintf(welcome, sizeof(welcome), "Welcome! You are client #%d\n", client->client_id);
    send(client->client_fd, welcome, strlen(welcome), 0);

    // Communication loop
    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        bytes_read = recv(client->client_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_read <= 0) {
            if (bytes_read == 0) {
                printf("[Client %d] Disconnected\n", client->client_id);
            } else {
                perror("recv failed");
            }
            break;
        }

        // Remove newline character if present
        buffer[strcspn(buffer, "\n")] = '\0';

        printf("[Client %d] Received: %s\n", client->client_id, buffer);

        // Check for exit command
        if (strcmp(buffer, "exit") == 0 || strcmp(buffer, "quit") == 0) {
            send(client->client_fd, "Goodbye!\n", 9, 0);
            break;
        }

        // Process command (example: simple commands)
        char response[BUFFER_SIZE];
        if (strcmp(buffer, "time") == 0) {
            time_t now = time(NULL);
            snprintf(response, sizeof(response), "Server time: %s", ctime(&now));
        } else if (strcmp(buffer, "help") == 0) {
            snprintf(response, sizeof(response), 
                     "Commands: time, help, echo <msg>, exit\n");
        } else if (strncmp(buffer, "echo ", 5) == 0) {
            snprintf(response, sizeof(response), "%s\n", buffer + 5);
        } else {
            snprintf(response, sizeof(response), "Unknown command: %s\n", buffer);
        }

        send(client->client_fd, response, strlen(response), 0);
    }

    // Cleanup
    close(client->client_fd);

    pthread_mutex_lock(&count_mutex);
    client_count--;
    pthread_mutex_unlock(&count_mutex);

    free(client);
    pthread_exit(NULL);
}

int main() {
    int server_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    pthread_t thread_id;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        exit(EXIT_FAILURE);
    }

    // Listen
    if (listen(server_fd, MAX_CONNECTIONS) < 0) {
        perror("Listen failed");
        exit(EXIT_FAILURE);
    }

    printf("=================================\n");
    printf("Multi-threaded TCP Server Started\n");
    printf("Listening on port %d\n", PORT);
    printf("=================================\n");

    // Accept connections
    while (1) {
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        // Check max connections
        pthread_mutex_lock(&count_mutex);
        if (client_count >= MAX_CONNECTIONS) {
            pthread_mutex_unlock(&count_mutex);
            char *msg = "Server is full. Try again later.\n";
            send(client_fd, msg, strlen(msg), 0);
            close(client_fd);
            continue;
        }
        client_count++;
        pthread_mutex_unlock(&count_mutex);

        // Allocate client info
        client_info_t *client = malloc(sizeof(client_info_t));
        client->client_fd = client_fd;
        client->client_addr = client_addr;

        pthread_mutex_lock(&count_mutex);
        static int id_counter = 0;
        client->client_id = ++id_counter;
        pthread_mutex_unlock(&count_mutex);

        // Create thread for client
        if (pthread_create(&thread_id, NULL, handle_client, (void *)client) != 0) {
            perror("Thread creation failed");
            close(client_fd);
            free(client);
            continue;
        }

        // Detach thread so resources are freed automatically
        pthread_detach(thread_id);
    }

    close(server_fd);
    return 0;
}
```

## Simple TCP Client (for testing)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sock_fd;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];

    // Create socket
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);

    // Convert IP address
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        perror("Invalid address");
        exit(EXIT_FAILURE);
    }

    // Connect to server
    if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        exit(EXIT_FAILURE);
    }

    printf("Connected to server!\n");

    // Communication loop
    while (1) {
        printf("Enter message: ");
        fgets(buffer, BUFFER_SIZE, stdin);

        // Send message
        send(sock_fd, buffer, strlen(buffer), 0);

        // Check for exit
        if (strncmp(buffer, "exit", 4) == 0) {
            break;
        }

        // Receive response
        memset(buffer, 0, BUFFER_SIZE);
        int bytes = recv(sock_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes <= 0) {
            printf("Server disconnected\n");
            break;
        }

        printf("Server: %s\n", buffer);
    }

    close(sock_fd);
    return 0;
}
```

## Compilation and Usage

```bash
# Compile basic server
gcc -o server server.c

# Compile multi-threaded server
gcc -o server_mt server_mt.c -pthread

# Compile client
gcc -o client client.c

# Run server
./server

# Run client (in another terminal)
./client
```

## Key Concepts

| Function | Purpose |
|----------|---------|
| `socket()` | Create a new socket |
| `bind()` | Assign address to socket |
| `listen()` | Mark socket as passive (server) |
| `accept()` | Accept incoming connection |
| `send()`/`recv()` | Send/receive data |
| `close()` | Close socket |

## Flow Diagram

```
Server                          Client
  |                               |
  | socket()                      |
  | bind()                        |
  | listen()                      |
  |                               | socket()
  | accept() <------------------- | connect()
  |                               |
  | recv() <--------------------- | send()
  | send() ---------------------> | recv()
  |                               |
  | close()                       | close()
```

This implementation includes error handling, socket options for address reuse, and demonstrates both single-threaded and multi-threaded approaches.

